import json
import logging
import time
from pathlib import Path

logger = logging.getLogger("agent.a2a")


class AgentCard:
    """生成/保存/加载 Agent Card。"""

    def __init__(self, config):
        self.config = config
        self.card_file = Path(config.agent_card_file)
        self.card_file.parent.mkdir(parents=True, exist_ok=True)

    def build(self, skill_manager=None, tool_registry=None):
        """汇总技能与工具，生成 Agent Card dict 并落盘。"""
        skills = []
        if skill_manager:
            skills = [
                {'name': s['name'], 'description': s.get('description', ''),
                 'intents': s.get('intents', [])}
                for s in skill_manager.list_skills()
            ]
        tools = []
        if tool_registry:
            tools = tool_registry.list_tools()
        card = {
            'agent_id': self.config.agent_id,
            'name': '数字员工 %s' % self.config.agent_id,
            'host': '127.0.0.1',
            'port': self.config.port,
            'chat_url': 'http://127.0.0.1:%d/chat' % self.config.port,
            'skills': skills,
            'tools': tools,
            'llm_configured': self.config.llm_configured,
            'updated_at': time.time(),
        }
        try:
            self.card_file.write_text(
                json.dumps(card, ensure_ascii=False, indent=2),
                encoding='utf-8')
            logger.info('Agent Card 已生成: %s（技能 %d，工具 %d）',
                        self.card_file, len(skills), len(tools))
        except OSError as e:
            logger.error('Agent Card 落盘失败: %s', e)
        return card

    def load(self):
        """读取已落盘的 Agent Card，不存在则返回 None。"""
        if not self.card_file.exists():
            return None
        try:
            return json.loads(self.card_file.read_text(encoding='utf-8'))
        except (ValueError, OSError):
            return None
